'use strict';

// X11 'Fixed' bitmap font, 7x13 bold weight - public domain (see
// LICENSE-x11-fixed.md). TrueType-converted from the original X11 core
// bitmap font by https://github.com/gamache/x11-fonts-ttf. This is the
